INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru, mnemonic_en, mnemonic_ru) VALUES
('ja', 'I', 'я', 'pronoun', NULL, 'A1', 1, 'ja', 'Ja jestem z Polski.', 'I am from Poland.', 'Я из Польши.', NULL, NULL),
('ty', 'you (singular informal)', 'ты', 'pronoun', NULL, 'A1', 2, 'tɨ', 'Ty jesteś miły.', 'You are nice.', 'Ты милый.', NULL, NULL),
('on', 'he', 'он', 'pronoun', 'masculine', 'A1', 3, 'ɔn', 'On jest nauczycielem.', 'He is a teacher.', 'Он учитель.', NULL, NULL),
('ona', 'she', 'она', 'pronoun', 'feminine', 'A1', 4, 'ɔna', 'Ona jest studentką.', 'She is a student.', 'Она студентка.', NULL, NULL),
('ono', 'it', 'оно', 'pronoun', 'neuter', 'A1', 5, 'ɔnɔ', 'Ono jest małe.', 'It is small.', 'Оно маленькое.', NULL, NULL),
('my', 'we', 'мы', 'pronoun', NULL, 'A1', 6, 'mɨ', 'My mieszkamy w Warszawie.', 'We live in Warsaw.', 'Мы живём в Варшаве.', NULL, NULL),
('wy', 'you (plural/formal)', 'вы', 'pronoun', NULL, 'A1', 7, 'vɨ', 'Wy jesteście przyjaciele.', 'You are friends.', 'Вы друзья.', NULL, NULL),
('oni', 'they (masculine/mixed)', 'они', 'pronoun', NULL, 'A1', 8, 'ɔɲi', 'Oni pracują tutaj.', 'They work here.', 'Они работают здесь.', NULL, NULL),
('one', 'they (feminine/neuter)', 'они', 'pronoun', NULL, 'A1', 9, 'ɔnɛ', 'One są zmęczone.', 'They are tired.', 'Они устали.', NULL, NULL),
('to', 'this/that/it', 'это', 'pronoun', NULL, 'A1', 10, 'tɔ', 'To jest dom.', 'This is a house.', 'Это дом.', NULL, NULL),
('kto', 'who', 'кто', 'pronoun', NULL, 'A1', 11, 'ktɔ', 'Kto to jest?', 'Who is it?', 'Кто это?', NULL, NULL),
('co', 'what', 'что', 'pronoun', NULL, 'A1', 12, 'tsɔ', 'Co to jest?', 'What is it?', 'Что это?', NULL, NULL),
('mój', 'my (masculine)', 'мой', 'pronoun', 'masculine', 'A1', 13, 'muj', 'To jest mój dom.', 'This is my house.', 'Это мой дом.', NULL, NULL),
('twój', 'your (singular)', 'твой', 'pronoun', 'masculine', 'A1', 14, 'tfuj', 'To jest twój samochód?', 'Is this your car?', 'Это твоя машина?', NULL, NULL),
('nasz', 'our', 'наш', 'pronoun', 'masculine', 'A1', 15, 'naʃ', 'To jest nasz dom.', 'This is our house.', 'Это наш дом.', NULL, NULL);
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru, mnemonic_en, mnemonic_ru) VALUES
('być', 'to be', 'быть', 'verb', NULL, 'A1', 16, 'bɨtɕ', 'Chcę być lekarzem.', 'I want to be a doctor.', 'Я хочу быть врачом.', NULL, NULL),
('jestem', 'I am', 'я есть', 'verb', NULL, 'A1', 17, 'jɛstɛm', 'Jestem szczęśliwy.', 'I am happy.', 'Я счастлив.', NULL, NULL),
('jesteś', 'you are', 'ты есть', 'verb', NULL, 'A1', 18, 'jɛstɛɕ', 'Jesteś miły.', 'You are nice.', 'Ты милый.', NULL, NULL),
('jest', 'is', 'есть', 'verb', NULL, 'A1', 19, 'jɛst', 'On jest wysoki.', 'He is tall.', 'Он высокий.', NULL, NULL),
('jesteśmy', 'we are', 'мы есть', 'verb', NULL, 'A1', 20, 'jɛstɛɕmɨ', 'Jesteśmy przyjaciółmi.', 'We are friends.', 'Мы друзья.', NULL, NULL),
('mieć', 'to have', 'иметь', 'verb', NULL, 'A1', 21, 'mjɛtɕ', 'Chcę mieć psa.', 'I want to have a dog.', 'Я хочу иметь собаку.', NULL, NULL),
('mam', 'I have', 'у меня есть', 'verb', NULL, 'A1', 22, 'mam', 'Mam kota.', 'I have a cat.', 'У меня есть кот.', NULL, NULL),
('masz', 'you have', 'у тебя есть', 'verb', NULL, 'A1', 23, 'maʃ', 'Masz czas?', 'Do you have time?', 'У тебя есть время?', NULL, NULL),
('ma', 'has', 'у него/неё есть', 'verb', NULL, 'A1', 24, 'ma', 'Ona ma książkę.', 'She has a book.', 'У неё есть книга.', NULL, NULL),
('móc', 'can/to be able', 'мочь', 'verb', NULL, 'A1', 25, 'mutsɕ', 'Mogę ci pomóc.', 'I can help you.', 'Я могу помочь тебе.', NULL, NULL),
('mogę', 'I can', 'я могу', 'verb', NULL, 'A1', 26, 'mɔgɛ', 'Mogę iść.', 'I can go.', 'Я могу идти.', NULL, NULL),
('możesz', 'you can', 'ты можешь', 'verb', NULL, 'A1', 27, 'mɔʐɛʃ', 'Możesz to zrobić.', 'You can do it.', 'Ты можешь это сделать.', NULL, NULL),
('może', 'can/may', 'может', 'verb', NULL, 'A1', 28, 'mɔʐɛ', 'On może przyjść.', 'He can come.', 'Он может прийти.', NULL, NULL),
('chcieć', 'to want', 'хотеть', 'verb', NULL, 'A1', 29, 'xtsɛtɕ', 'Chcę jeść.', 'I want to eat.', 'Я хочу есть.', NULL, NULL),
('chcę', 'I want', 'я хочу', 'verb', NULL, 'A1', 30, 'xtsɛ', 'Chcę kawę.', 'I want coffee.', 'Я хочу кофе.', NULL, NULL),
('chcesz', 'you want', 'ты хочешь', 'verb', NULL, 'A1', 31, 'xtsɛʃ', 'Chcesz herbatę?', 'Do you want tea?', 'Ты хочешь чай?', NULL, NULL),
('chce', 'wants', 'хочет', 'verb', NULL, 'A1', 32, 'xtsɛ', 'Ona chce iść.', 'She wants to go.', 'Она хочет идти.', NULL, NULL),
('wiedzieć', 'to know', 'знать', 'verb', NULL, 'A1', 33, 'vjɛd͡ʑɛtɕ', 'Chcę wiedzieć.', 'I want to know.', 'Я хочу знать.', NULL, NULL),
('wiem', 'I know', 'я знаю', 'verb', NULL, 'A1', 34, 'vjɛm', 'Nie wiem.', 'I don''t know.', 'Я не знаю.', 'One of the most useful phrases!', 'Одна из самых полезных фраз!'),
('wiesz', 'you know', 'ты знаешь', 'verb', NULL, 'A1', 35, 'vjɛʃ', 'Czy wiesz, gdzie to jest?', 'Do you know where it is?', 'Ты знаешь, где это?', NULL, NULL),
('wie', 'knows', 'знает', 'verb', NULL, 'A1', 36, 'vjɛ', 'On nie wie.', 'He doesn''t know.', 'Он не знает.', NULL, NULL),
('robić', 'to do/make', 'делать', 'verb', NULL, 'A1', 37, 'rɔbit͡ɕ', 'Co robisz?', 'What are you doing?', 'Что ты делаешь?', NULL, NULL),
('robię', 'I do/make', 'я делаю', 'verb', NULL, 'A1', 38, 'rɔbʲɛ', 'Robię kolację.', 'I am making dinner.', 'Я готовлю ужин.', NULL, NULL),
('mówić', 'to speak/say', 'говорить', 'verb', NULL, 'A1', 39, 'muvit͡ɕ', 'Mówię po polsku.', 'I speak Polish.', 'Я говорю по-польски.', NULL, NULL),
('mówię', 'I speak/say', 'я говорю', 'verb', NULL, 'A1', 40, 'muvʲɛ', 'Mówię prawdę.', 'I speak the truth.', 'Я говорю правду.', NULL, NULL),
('iść', 'to go (on foot)', 'идти', 'verb', NULL, 'A1', 41, 'iɕtɕ', 'Chcę iść do domu.', 'I want to go home.', 'Я хочу идти домой.', NULL, NULL),
('idę', 'I go/am going', 'я иду', 'verb', NULL, 'A1', 42, 'idɛ', 'Idę do szkoły.', 'I am going to school.', 'Я иду в школу.', NULL, NULL),
('jechać', 'to go (by vehicle)', 'ехать', 'verb', NULL, 'A1', 43, 'jɛxat͡ɕ', 'Jadę autobusem.', 'I''m going by bus.', 'Я еду на автобусе.', NULL, NULL),
('jadę', 'I go (by vehicle)', 'я еду', 'verb', NULL, 'A1', 44, 'jadɛ', 'Jadę do Warszawy.', 'I am going to Warsaw.', 'Я еду в Варшаву.', NULL, NULL),
('mieszkać', 'to live/reside', 'жить', 'verb', NULL, 'A1', 45, 'mʲɛʃkat͡ɕ', 'Mieszkam w Polsce.', 'I live in Poland.', 'Я живу в Польше.', NULL, NULL),
('mieszkam', 'I live', 'я живу', 'verb', NULL, 'A1', 46, 'mʲɛʃkam', 'Mieszkam w Krakowie.', 'I live in Krakow.', 'Я живу в Кракове.', NULL, NULL),
('pracować', 'to work', 'работать', 'verb', NULL, 'A1', 47, 'prat͡sɔvat͡ɕ', 'Pracuję w szkole.', 'I work at school.', 'Я работаю в школе.', NULL, NULL),
('pracuję', 'I work', 'я работаю', 'verb', NULL, 'A1', 48, 'prat͡sujɛ', 'Pracuję codziennie.', 'I work every day.', 'Я работаю каждый день.', NULL, NULL),
('uczyć się', 'to study/learn', 'учиться', 'verb', NULL, 'A1', 49, 'ut͡ʂɨt͡ɕ ɕɛ', 'Uczę się polskiego.', 'I am learning Polish.', 'Я учу польский.', NULL, NULL),
('uczę się', 'I study/learn', 'я учусь', 'verb', NULL, 'A1', 50, 'ut͡ʂɛ ɕɛ', 'Uczę się języków.', 'I learn languages.', 'Я учу языки.', NULL, NULL),
('lubić', 'to like', 'любить/нравиться', 'verb', NULL, 'A1', 51, 'lubit͡ɕ', 'Lubię kawę.', 'I like coffee.', 'Я люблю кофе.', NULL, NULL),
('lubię', 'I like', 'мне нравится', 'verb', NULL, 'A1', 52, 'lubʲɛ', 'Lubię czytać.', 'I like to read.', 'Мне нравится читать.', NULL, NULL),
('jeść', 'to eat', 'есть', 'verb', NULL, 'A1', 53, 'jɛɕt͡ɕ', 'Czas jeść.', 'Time to eat.', 'Время есть.', NULL, NULL),
('jem', 'I eat', 'я ем', 'verb', NULL, 'A1', 54, 'jɛm', 'Jem śniadanie.', 'I eat breakfast.', 'Я ем завтрак.', NULL, NULL),
('pić', 'to drink', 'пить', 'verb', NULL, 'A1', 55, 'pit͡ɕ', 'Chcę pić wodę.', 'I want to drink water.', 'Я хочу пить воду.', NULL, NULL),
('piję', 'I drink', 'я пью', 'verb', NULL, 'A1', 56, 'pijɛ', 'Piję kawę.', 'I drink coffee.', 'Я пью кофе.', NULL, NULL),
('pisać', 'to write', 'писать', 'verb', NULL, 'A1', 57, 'pisat͡ɕ', 'Piszę list.', 'I am writing a letter.', 'Я пишу письмо.', NULL, NULL),
('piszę', 'I write', 'я пишу', 'verb', NULL, 'A1', 58, 'piʃɛ', 'Piszę email.', 'I am writing an email.', 'Я пишу email.', NULL, NULL),
('czytać', 'to read', 'читать', 'verb', NULL, 'A1', 59, 't͡ʂɨtat͡ɕ', 'Czytam książkę.', 'I am reading a book.', 'Я читаю книгу.', NULL, NULL),
('czytam', 'I read', 'я читаю', 'verb', NULL, 'A1', 60, 't͡ʂɨtam', 'Czytam gazety.', 'I read newspapers.', 'Я читаю газеты.', NULL, NULL),
('słuchać', 'to listen', 'слушать', 'verb', NULL, 'A1', 61, 'swuxat͡ɕ', 'Słucham muzyki.', 'I listen to music.', 'Я слушаю музыку.', NULL, NULL),
('słucham', 'I listen', 'я слушаю', 'verb', NULL, 'A1', 62, 'swuxam', 'Słucham radia.', 'I listen to the radio.', 'Я слушаю радио.', NULL, NULL),
('patrzeć', 'to look/watch', 'смотреть', 'verb', NULL, 'A1', 63, 'pat͡ʂɛt͡ɕ', 'Patrzę na ciebie.', 'I am looking at you.', 'Я смотрю на тебя.', NULL, NULL),
('patrzę', 'I look/watch', 'я смотрю', 'verb', NULL, 'A1', 64, 'pat͡ʂɛ', 'Patrzę na ekran.', 'I am looking at the screen.', 'Я смотрю на экран.', NULL, NULL),
('oglądać', 'to watch', 'смотреть', 'verb', NULL, 'A1', 65, 'ɔglɔndat͡ɕ', 'Oglądam telewizję.', 'I watch television.', 'Я смотрю телевизор.', NULL, NULL),
('oglądam', 'I watch', 'я смотрю', 'verb', NULL, 'A1', 66, 'ɔglɔndam', 'Oglądam film.', 'I am watching a movie.', 'Я смотрю фильм.', NULL, NULL),
('rozumieć', 'to understand', 'понимать', 'verb', NULL, 'A1', 67, 'rɔzumʲɛt͡ɕ', 'Nie rozumiem.', 'I don''t understand.', 'Я не понимаю.', 'Very useful phrase!', 'Очень полезная фраза!'),
('rozumiem', 'I understand', 'я понимаю', 'verb', NULL, 'A1', 68, 'rɔzumʲɛm', 'Rozumiem po polsku.', 'I understand Polish.', 'Я понимаю по-польски.', NULL, NULL),
('kupować', 'to buy', 'покупать', 'verb', NULL, 'A1', 69, 'kupɔvat͡ɕ', 'Kupuję chleb.', 'I buy bread.', 'Я покупаю хлеб.', NULL, NULL),
('kupuję', 'I buy', 'я покупаю', 'verb', NULL, 'A1', 70, 'kupujɛ', 'Kupuję jedzenie.', 'I am buying food.', 'Я покупаю еду.', NULL, NULL),
('sprzedawać', 'to sell', 'продавать', 'verb', NULL, 'A1', 71, 'spʂɛdavat͡ɕ', 'Sprzedaję samochód.', 'I am selling a car.', 'Я продаю машину.', NULL, NULL),
('kosztować', 'to cost', 'стоить', 'verb', NULL, 'A1', 72, 'kɔʃtɔvat͡ɕ', 'Ile to kosztuje?', 'How much does it cost?', 'Сколько это стоит?', NULL, NULL),
('kosztuje', 'it costs', 'это стоит', 'verb', NULL, 'A1', 73, 'kɔʃtujɛ', 'To kosztuje dziesięć złotych.', 'It costs ten zlotys.', 'Это стоит десять злотых.', NULL, NULL),
('płacić', 'to pay', 'платить', 'verb', NULL, 'A1', 74, 'pwat͡ɕit͡ɕ', 'Płacę kartą.', 'I pay by card.', 'Я плачу картой.', NULL, NULL),
('płacę', 'I pay', 'я плачу', 'verb', NULL, 'A1', 75, 'pwat͡sɛ', 'Płacę gotówką.', 'I pay cash.', 'Я плачу наличными.', NULL, NULL),
('zaczynać', 'to begin/start', 'начинать', 'verb', NULL, 'A1', 76, 'zat͡ʂɨnat͡ɕ', 'Zaczynam pracę.', 'I start work.', 'Я начинаю работу.', NULL, NULL),
('kończyć', 'to finish/end', 'заканчивать', 'verb', NULL, 'A1', 77, 'kɔɲt͡ʂɨt͡ɕ', 'Kończę pracę.', 'I finish work.', 'Я заканчиваю работу.', NULL, NULL),
('pomagać', 'to help', 'помогать', 'verb', NULL, 'A1', 78, 'pɔmagat͡ɕ', 'Pomagam mamie.', 'I help my mother.', 'Я помогаю маме.', NULL, NULL),
('dziękować', 'to thank', 'благодарить', 'verb', NULL, 'A1', 79, 'd͡ʑɛnkɔvat͡ɕ', 'Dziękuję za pomoc.', 'Thank you for help.', 'Спасибо за помощь.', NULL, NULL),
('prosić', 'to ask/request', 'просить', 'verb', NULL, 'A1', 80, 'prɔɕit͡ɕ', 'Proszę o pomoc.', 'I ask for help.', 'Прошу помощи.', NULL, NULL);
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru, mnemonic_en, mnemonic_ru) VALUES
('zero', 'zero', 'ноль', 'numeral', NULL, 'A1', 81, 'zɛrɔ', 'To jest zero.', 'This is zero.', 'Это ноль.', NULL, NULL),
('jeden', 'one', 'один', 'numeral', NULL, 'A1', 82, 'jɛdɛn', 'Mam jeden brat.', 'I have one brother.', 'У меня один брат.', NULL, NULL),
('dwa', 'two', 'два', 'numeral', NULL, 'A1', 83, 'dva', 'Dwa plus dwa równa się cztery.', 'Two plus two equals four.', 'Два плюс два равно четыре.', NULL, NULL),
('trzy', 'three', 'три', 'numeral', NULL, 'A1', 84, 't͡ʂɨ', 'Mam trzy siostry.', 'I have three sisters.', 'У меня три сестры.', NULL, NULL),
('cztery', 'four', 'четыре', 'numeral', NULL, 'A1', 85, 't͡ʂtɛrɨ', 'Cztery pory roku.', 'Four seasons.', 'Четыре времени года.', NULL, NULL),
('pięć', 'five', 'пять', 'numeral', NULL, 'A1', 86, 'pʲɛɲt͡ɕ', 'Mam pięć lat.', 'I am five years old.', 'Мне пять лет.', NULL, NULL),
('sześć', 'six', 'шесть', 'numeral', NULL, 'A1', 87, 'ʃɛɕt͡ɕ', 'Jest szósta godzina.', 'It is six o''clock.', 'Шесть часов.', NULL, NULL),
('siedem', 'seven', 'семь', 'numeral', NULL, 'A1', 88, 'ɕɛdɛm', 'Siedem dni w tygodniu.', 'Seven days in a week.', 'Семь дней в неделю.', NULL, NULL),
('osiem', 'eight', 'восемь', 'numeral', NULL, 'A1', 89, 'ɔɕɛm', 'Mam osiem lat.', 'I am eight years old.', 'Мне восемь лет.', NULL, NULL),
('dziewięć', 'nine', 'девять', 'numeral', NULL, 'A1', 90, 'd͡ʑɛvʲɛɲt͡ɕ', 'Dziewięć plus jeden.', 'Nine plus one.', 'Девять плюс один.', NULL, NULL),
('dziesięć', 'ten', 'десять', 'numeral', NULL, 'A1', 91, 'd͡ʑɛɕɛɲt͡ɕ', 'Dziesięć palców.', 'Ten fingers.', 'Десять пальцев.', NULL, NULL),
('jedenaście', 'eleven', 'одиннадцать', 'numeral', NULL, 'A1', 92, 'jɛdɛnaɕt͡ɕɛ', 'Jest jedenasta.', 'It is eleven.', 'Одиннадцать.', NULL, NULL),
('dwanaście', 'twelve', 'двенадцать', 'numeral', NULL, 'A1', 93, 'dvanaɕt͡ɕɛ', 'Dwanaście miesięcy.', 'Twelve months.', 'Двенадцать месяцев.', NULL, NULL),
('trzynaście', 'thirteen', 'тринадцать', 'numeral', NULL, 'A1', 94, 't͡ʂɨznaɕt͡ɕɛ', 'Trzynaście lat.', 'Thirteen years.', 'Тринадцать лет.', NULL, NULL),
('czternaście', 'fourteen', 'четырнадцать', 'numeral', NULL, 'A1', 95, 't͡ʂtɛrnaɕt͡ɕɛ', 'Mam czternaście lat.', 'I am fourteen.', 'Мне четырнадцать.', NULL, NULL),
('piętnaście', 'fifteen', 'пятнадцать', 'numeral', NULL, 'A1', 96, 'pʲɛntnaɕt͡ɕɛ', 'Piętnaście minut.', 'Fifteen minutes.', 'Пятнадцать минут.', NULL, NULL),
('szesnaście', 'sixteen', 'шестнадцать', 'numeral', NULL, 'A1', 97, 'ʃɛsnaɕt͡ɕɛ', 'Mam szesnaście lat.', 'I am sixteen.', 'Мне шестнадцать.', NULL, NULL),
('siedemnaście', 'seventeen', 'семнадцать', 'numeral', NULL, 'A1', 98, 'ɕɛdɛmnaɕt͡ɕɛ', 'Siedemnaście osób.', 'Seventeen people.', 'Семнадцать человек.', NULL, NULL),
('osiemnaście', 'eighteen', 'восемнадцать', 'numeral', NULL, 'A1', 99, 'ɔɕɛmnaɕt͡ɕɛ', 'Mam osiemnaście lat.', 'I am eighteen.', 'Мне восемнадцать.', NULL, NULL),
('dziewiętnaście', 'nineteen', 'девятнадцать', 'numeral', NULL, 'A1', 100, 'd͡ʑɛvʲɛntnaɕt͡ɕɛ', 'Dziewiętnaście złotych.', 'Nineteen zlotys.', 'Девятнадцать злотых.', NULL, NULL),
('dwadzieścia', 'twenty', 'двадцать', 'numeral', NULL, 'A1', 101, 'dvad͡ʑɛɕt͡ɕa', 'Dwadzieścia lat.', 'Twenty years.', 'Двадцать лет.', NULL, NULL),
('trzydzieści', 'thirty', 'тридцать', 'numeral', NULL, 'A1', 102, 't͡ʂɨd͡ʑɛɕt͡ɕi', 'Trzydzieści minut.', 'Thirty minutes.', 'Тридцать минут.', NULL, NULL),
('czterdzieści', 'forty', 'сорок', 'numeral', NULL, 'A1', 103, 't͡ʂtɛrd͡ʑɛɕt͡ɕi', 'Czterdzieści lat.', 'Forty years.', 'Сорок лет.', NULL, NULL),
('pięćdziesiąt', 'fifty', 'пятьдесят', 'numeral', NULL, 'A1', 104, 'pʲɛɲd͡ʑɛɕɔnt', 'Pięćdziesiąt procent.', 'Fifty percent.', 'Пятьдесят процентов.', NULL, NULL),
('sześćdziesiąt', 'sixty', 'шестьдесят', 'numeral', NULL, 'A1', 105, 'ʃɛɕd͡ʑɛɕɔnt', 'Sześćdziesiąt sekund.', 'Sixty seconds.', 'Шестьдесят секунд.', NULL, NULL),
('sto', 'hundred', 'сто', 'numeral', NULL, 'A1', 106, 'stɔ', 'Sto złotych.', 'One hundred zlotys.', 'Сто злотых.', NULL, NULL),
('tysiąc', 'thousand', 'тысяча', 'numeral', NULL, 'A1', 107, 'tɨɕɔnt͡s', 'Tysiąc ludzi.', 'One thousand people.', 'Тысяча людей.', NULL, NULL),
('pierwszy', 'first', 'первый', 'numeral', 'masculine', 'A1', 108, 'pʲɛrfʃɨ', 'To jest pierwszy dzień.', 'This is the first day.', 'Это первый день.', NULL, NULL),
('drugi', 'second', 'второй', 'numeral', 'masculine', 'A1', 109, 'drugi', 'Drugi raz.', 'Second time.', 'Второй раз.', NULL, NULL),
('trzeci', 'third', 'третий', 'numeral', 'masculine', 'A1', 110, 't͡ʂɛt͡ɕi', 'Trzecia godzina.', 'Third hour.', 'Третий час.', NULL, NULL);
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru, mnemonic_en, mnemonic_ru) VALUES
('kolor', 'color', 'цвет', 'noun', 'masculine', 'A1', 111, 'kɔlɔr', 'Jaki jest twój ulubiony kolor?', 'What is your favorite color?', 'Какой твой любимый цвет?', NULL, NULL),
('biały', 'white', 'белый', 'adjective', NULL, 'A1', 112, 'bʲawɨ', 'To jest biały dom.', 'This is a white house.', 'Это белый дом.', NULL, NULL),
